"""Audit fuzz: random/garbage proposals must never crash and rarely validate."""
import random, sys, json, copy
sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/tmp')
import gen, para, algo

rng = random.Random(int(sys.argv[1]) if len(sys.argv)>1 else 0)
def rand_cell(rng, V):
    r = rng.random()
    if r < 0.2: return None
    if r < 0.3: return rng.choice([True, False, 1.5, "x", [], {}])
    if r < 0.5: return rng.randint(-10**31, 10**31)
    return rng.randint(-5, 10**6)

accepted = 0; total = 0
for it in range(120):
    prof = gen.gen_profile(rng)
    cal = para.build_calib(prof)
    fb = gen.gen_fabric(rng, cal.K if cal.feasible else 2, maxP=8)
    plan = algo.compile_plan(prof, fb)
    for trial in range(6):
        m = copy.deepcopy(plan)
        K = prof['groups']; N = fb['n']; P = m.get('period_rounds') or 1
        r = rng.random()
        if isinstance(m.get('bounds_as'), list):
            if r < 0.25:
                m['bounds_as'][rng.randrange(P)][rng.randrange(N)] = rand_cell(rng, 0)
            elif r < 0.5:
                m['age_rounds'][rng.randrange(P)][rng.randrange(N)] = rand_cell(rng, 0)
            elif r < 0.75:
                p = rng.randrange(P); i = rng.randrange(N)
                m['pred'][p][i] = rng.choice([None, [rng.randint(-3, 10**7), rng.randint(-3, 4*len(fb['links'])+4)],
                                              [None, 0], [], "x", 5])
            else:
                m[rng.choice(list(m.keys()))] = rng.choice([None, 0, "x", [], {}, True])
        else:
            m[rng.choice(list(m.keys()))] = rng.choice([None, 0, 1, "x", [], {}, True, [0]])
        total += 1
        res = algo.audit(prof, fb, m)
        assert set(res.keys()) == {'valid'} and type(res['valid']) is bool, res
        if res['valid']:
            accepted += 1
            if m != plan:
                print('ACCEPTED MUTATION!', json.dumps(m)[:600], json.dumps(fb)[:400])
print('total', total, 'accepted', accepted)
